666	    private Mono<List<MailboxRenamedResult>> doRenameMailbox(Mailbox mailbox, MailboxPath newMailboxPath, MailboxSession fromSession, MailboxSession toSession, MailboxMapper mapper) {
667	        // TODO put this into a serilizable transaction
668	
669	        ImmutableList.Builder<MailboxRenamedResult> resultBuilder = ImmutableList.builder();
670	
671	        MailboxPath from = mailbox.generateAssociatedPath();
672	        mailbox.setNamespace(newMailboxPath.getNamespace());
673	        mailbox.setUser(newMailboxPath.getUser());
674	        mailbox.setName(newMailboxPath.getName());
675	        // Find submailboxes
676	        MailboxQuery.UserBound query = MailboxQuery.builder()
677	            .userAndNamespaceFrom(from)
678	            .expression(new PrefixedWildcard(from.getName() + fromSession.getPathDelimiter()))
679	            .build()
680	            .asUserBound();
681	
682	        return mapper.rename(mailbox)
683	            .map(mailboxId -> {
684	                resultBuilder.add(new MailboxRenamedResult(mailboxId, from, newMailboxPath));
685	                return mailboxId;
686	            })
687	            .then(Mono.from(renameSubMailboxes(newMailboxPath, toSession, mapper, from, query, resultBuilder)))
688	            .then(Mono.defer(() -> Flux.fromIterable(resultBuilder.build())
689	                .concatMap(result -> eventBus.dispatch(EventFactory.mailboxRenamed()
690	                        .randomEventId()
691	                        .mailboxSession(fromSession)
692	                        .mailboxId(result.getMailboxId())
693	                        .oldPath(result.getOriginPath())
694	                        .newPath(result.getDestinationPath())
695	                        .build(),
696	                    new MailboxIdRegistrationKey(result.getMailboxId())))
697	                .then()))
698	            .then(Mono.fromCallable(resultBuilder::build));
