522	    private Mono<Mailbox> doDeleteMailbox(MailboxMapper mailboxMapper, Mailbox mailbox, MailboxSession session) {
523	        MessageMapper messageMapper = mailboxSessionMapperFactory.getMessageMapper(session);
524	
525	        Mono<QuotaRoot> quotaRootPublisher = Mono.fromCallable(() -> quotaRootResolver.getQuotaRoot(mailbox.generateAssociatedPath()));
526	        Mono<Long> messageCountPublisher = Mono.from(messageMapper.getMailboxCountersReactive(mailbox))
527	            .map(MailboxCounters::getCount);
528	
529	        return quotaRootPublisher.zipWith(messageCountPublisher).flatMap(quotaRootWithMessageCount -> messageMapper.findInMailboxReactive(mailbox, MessageRange.all(), MessageMapper.FetchType.METADATA, UNLIMITED)
530	            .map(message -> MetadataWithMailboxId.from(message.metaData(), message.getMailboxId()))
531	            .collect(ImmutableList.toImmutableList())
532	            .flatMap(metadata -> {
533	                long totalSize = metadata.stream()
534	                    .mapToLong(MetadataWithMailboxId::getSize)
535	                    .sum();
536	
537	                return preDeletionHooks.runHooks(PreDeletionHook.DeleteOperation.from(metadata))
538	                    .then(mailboxMapper.delete(mailbox))
539	                    .then(eventBus.dispatch(EventFactory.mailboxDeleted()
540	                            .randomEventId()
541	                            .mailboxSession(session)
542	                            .mailbox(mailbox)
543	                            .quotaRoot(quotaRootWithMessageCount.getT1())
544	                            .mailboxACL(mailbox.getACL())
545	                            .quotaCount(QuotaCountUsage.count(quotaRootWithMessageCount.getT2()))
546	                            .quotaSize(QuotaSizeUsage.size(totalSize))
547	                            .build(),
548	                        new MailboxIdRegistrationKey(mailbox.getMailboxId())));
549	            })
550	            .retryWhen(RETRY_BACKOFF_SPEC)
551	            // We need to create a copy of the mailbox as maybe we can not refer to the real
552	            // mailbox once we remove it
553	            .thenReturn(new Mailbox(mailbox)));
554	    }

